const BOOK_NAMES={mat:'마태복음',mrk:'마가복음',luk:'누가복음',jhn:'요한복음',act:'사도행전',rom:'로마서','1co':'고린도전서','2co':'고린도후서',gal:'갈라디아서',eph:'에베소서',php:'빌립보서',col:'골로새서','1th':'데살로니가전서','2th':'데살로니가후서','1ti':'디모데전서','2ti':'디모데후서',tit:'디도서',phm:'빌레몬서',heb:'히브리서',jas:'야고보서','1pe':'베드로전서','2pe':'베드로후서','1jn':'요한일서','2jn':'요한이서','3jn':'요한삼서',jud:'유다서',rev:'요한계시록'};
export const NEW_TESTAMENT_CODES=new Set(Object.keys(BOOK_NAMES));
export function newTestamentMonologues(n,occurrences){
 const out=[];
 for(const [code,chap,name,verses,lines,emotion,lineRefs] of rows){
  if(n.name!==name&&!(name==='예수'&&n.name==='예수님'))continue;
  if(!occurrences.some(p=>p.code===code&&p.chap===chap))continue;
  lines.forEach((text,index)=>out.push({text,ref:`${BOOK_NAMES[code]} ${chap}:${lineRefs?.[index]||verses}`,emotion,origin:'authored'}));
 }
 return out;
}
